window.kbPageData["views/entry/k-4fc01c89e40a0023"] = {"key":"entry/k-4fc01c89e40a0023","state":{"route":"entry/k-4fc01c89e40a0023"},"node":{"id":"k-4fc01c89e40a0023","mode":"k","title":"《2025 年国民经济和社会发展统计公报》发布（2 月 28 日）","type":"事实与事件","domain":"经济","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["finance"],"主类":["事实与事件"],"出处性质":["时政汇编"],"学科":["经济"],"时间索引":["年度事件或数据"],"来源主题":["重要事件"],"资料类别":["时政"]},"eventTags":[{"year":2026,"title":"《2025 年国民经济和社会发展统计公报》发布（2 月 28 日）","slug":"637ebada3a7f"}],"directorySummary":"考点四 《2025 年国民经济和社会发展统计公报》发布（2 月 28 日）\n2 月 28 日，国家统计局发布《2025 年国民经济和社会发展统计公报》。2025 年我国 GDP 比上\n年增长 5.0%，经济总量首次突破 140 万亿元大关，圆满完成预期目标任务；人均 GDP 达 99665\n元，比上…","sources":[{"id":"3249ed40d6b7e89d","label":"《2025 年国民经济和社会发展统计公报》发布（2 月 28 日）","topic":"重要事件","category":"时政","text":"考点四 《2025 年国民经济和社会发展统计公报》发布（2 月 28 日）\n2 月 28 日，国家统计局发布《2025 年国民经济和社会发展统计公报》。2025 年我国 GDP 比上\n年增长 5.0%，经济总量首次突破 140 万亿元大关，圆满完成预期目标任务；人均 GDP 达 99665\n元，比上年增长 5.1%。我国对世界经济增长贡献率预计保持在 30%左右，持续成为世界经济增\n长的最大贡献者和最强稳定锚，稳居世界第二大经济体，经济总量占全球六分之一左右。全社\n会研究与试验发展（R&D）经费投入比上年增长 8.1%，与 GDP 之比达 2.80%，首次超过 OECD 国\n家平均水平，其中基础研究经费占比达 7.08%。","source":{"doc":"4e539a366dce19555ccf","first":24,"last":24,"page":24,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"finance","title":"财政金融与宏观调控"}],"units":{"k-4fc01c89e40a0023":[]}};
